import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { ActivatedRoute, Router, provideRouter } from '@angular/router';
import { BookingStore } from '../core/booking';
import { Checkout } from './checkout';

describe('Checkout', () => {
  beforeEach(() => {
    sessionStorage.clear();
    TestBed.configureTestingModule({
      providers: [
        provideRouter([]),
        provideHttpClient(),
        provideHttpClientTesting(),
        { provide: ActivatedRoute, useValue: { snapshot: { paramMap: new Map([['id', '1']]) } } },
      ],
    });
    const store = TestBed.inject(BookingStore);
    store.start(1);
    store.setSeats(['R7C12', 'R15C1', 'R15C2']);
  });

  const open = () => {
    const fixture = TestBed.createComponent(Checkout);
    return { fixture, el: fixture.nativeElement as HTMLElement };
  };
  const q = (el: HTMLElement, id: string) => el.querySelector<HTMLElement>(`[data-testid="${id}"]`);
  const type = async (fixture: { whenStable(): Promise<void> }, el: HTMLElement, id: string, value: string) => {
    const input = q(el, id) as HTMLInputElement;
    input.value = value;
    input.dispatchEvent(new Event('input'));
    await fixture.whenStable();
  };
  const blur = async (fixture: { whenStable(): Promise<void> }, el: HTMLElement, id: string) => {
    q(el, id)!.dispatchEvent(new Event('blur'));
    await fixture.whenStable();
  };

  it('shows the pay total and labels', async () => {
    const { fixture, el } = open();
    await fixture.whenStable();
    expect(q(el, 'pay-button')?.textContent?.trim()).toBe('Pay 121.00 PLN');
    expect(q(el, 'first-name-label')?.textContent).toBe('First name *');
    expect(q(el, 'phone-label')?.textContent).toBe('Phone number');
  });

  it('validates fields after blur and re-checks confirm email', async () => {
    const { fixture, el } = open();
    await fixture.whenStable();
    expect(q(el, 'first-name-error')).toBeNull();
    await blur(fixture, el, 'first-name-input');
    expect(q(el, 'first-name-error')?.textContent).toBe('First name is required');
    await type(fixture, el, 'first-name-input', 'A');
    expect(q(el, 'first-name-error')?.textContent).toBe('First name must be at least 2 characters');
    await type(fixture, el, 'first-name-input', 'An');
    expect(q(el, 'first-name-error')).toBeNull();

    await type(fixture, el, 'email-input', 'a@b');
    await blur(fixture, el, 'email-input');
    expect(q(el, 'email-error')?.textContent).toBe('Enter a valid email address');
    await type(fixture, el, 'confirm-email-input', 'a@b.pl');
    await blur(fixture, el, 'confirm-email-input');
    expect(q(el, 'confirm-email-error')?.textContent).toBe('Email addresses do not match');
    await type(fixture, el, 'email-input', 'a@b.pl');
    expect(q(el, 'confirm-email-error')).toBeNull();
    expect(q(el, 'email-error')).toBeNull();

    await type(fixture, el, 'phone-input', '12345678');
    await blur(fixture, el, 'phone-input');
    expect(q(el, 'phone-error')?.textContent).toBe('Phone number must be exactly 9 digits');
    expect(TestBed.inject(BookingStore).current()?.form.email).toBe('a@b.pl');
  });

  it('refuses to pay an invalid form, then pays a valid one', async () => {
    const { fixture, el } = open();
    const router = TestBed.inject(Router);
    const navigate = vi.spyOn(router, 'navigateByUrl').mockResolvedValue(true);
    const http = TestBed.inject(HttpTestingController);
    await fixture.whenStable();
    q(el, 'pay-button')!.click();
    await fixture.whenStable();
    http.expectNone('http://localhost:3000/reservations');
    expect(q(el, 'terms-error')?.textContent).toBe('You must accept the terms and conditions');
    expect(q(el, 'confirm-email-error')?.textContent).toBe('Confirm email is required');
    expect(document.querySelector('[data-testid=toast]')?.textContent).toBe('The form contains errors');

    await type(fixture, el, 'first-name-input', 'Anna');
    await type(fixture, el, 'last-name-input', 'Kowalska');
    await type(fixture, el, 'email-input', 'anna@example.com');
    await type(fixture, el, 'confirm-email-input', 'anna@example.com');
    (q(el, 'terms-checkbox')!.querySelector('input') as HTMLInputElement).click();
    await fixture.whenStable();
    q(el, 'pay-button')!.click();
    await fixture.whenStable();
    const req = http.expectOne('http://localhost:3000/reservations');
    expect(req.request.body).toEqual({
      screeningId: 1,
      seats: ['R7C12', 'R15C1', 'R15C2'],
      customer: { firstName: 'Anna', lastName: 'Kowalska', email: 'anna@example.com', phone: '' },
      totalPrice: 121,
    });
    expect(q(el, 'pay-button')?.textContent?.trim()).toBe('Processing…');
    expect((q(el, 'pay-button') as HTMLButtonElement).disabled).toBe(true);
    req.flush({ id: 1 });
    await fixture.whenStable();
    expect(navigate).toHaveBeenCalledWith('/confirmation');
    expect(TestBed.inject(BookingStore).current()).toMatchObject({ paid: true, email: 'anna@example.com' });
  });
});

import { Component, DestroyRef, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { AbstractControl, FormControl, FormGroup, ReactiveFormsModule, ValidationErrors, ValidatorFn } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { ActivatedRoute, Router } from '@angular/router';
import { Api, parseId } from '../core/api';
import { BookingStore } from '../core/booking';
import { formatPrice } from '../core/seats';
import { ToastService } from '../core/toast';

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const PHONE_PATTERN = /^[0-9]{9}$/;

const fail = (msg: string): ValidationErrors => ({ msg });

const minLength =
  (label: string): ValidatorFn =>
  (control) =>
    !control.value ? fail(`${label} is required`) : control.value.length < 2 ? fail(`${label} must be at least 2 characters`) : null;

const emailRule: ValidatorFn = (control) =>
  !control.value ? fail('Email is required') : EMAIL_PATTERN.test(control.value) ? null : fail('Enter a valid email address');

const phoneRule: ValidatorFn = (control) =>
  !control.value || PHONE_PATTERN.test(control.value) ? null : fail('Phone number must be exactly 9 digits');

const termsRule: ValidatorFn = (control) => (control.value ? null : fail('You must accept the terms and conditions'));

const confirmEmailRule =
  (email: AbstractControl): ValidatorFn =>
  (control) =>
    !control.value
      ? fail('Confirm email is required')
      : control.value === email.value
        ? null
        : fail('Email addresses do not match');

@Component({
  selector: 'app-checkout',
  imports: [ReactiveFormsModule, MatButtonModule, MatCheckboxModule, MatFormFieldModule, MatInputModule],
  templateUrl: './checkout.html',
  styleUrl: './checkout.scss',
})
export class Checkout {
  private readonly api = inject(Api);
  private readonly router = inject(Router);
  private readonly toast = inject(ToastService);
  private readonly destroyRef = inject(DestroyRef);
  private readonly screeningId = parseId(inject(ActivatedRoute).snapshot.paramMap.get('id'));
  protected readonly booking = inject(BookingStore);

  protected readonly format = formatPrice;
  protected readonly processing = signal(false);

  protected readonly form: FormGroup<{
    firstName: FormControl<string>;
    lastName: FormControl<string>;
    email: FormControl<string>;
    confirmEmail: FormControl<string>;
    phone: FormControl<string>;
    terms: FormControl<boolean>;
  }>;

  constructor() {
    const saved = this.booking.current()!.form;
    const email = new FormControl(saved.email, { nonNullable: true, validators: [emailRule] });
    this.form = new FormGroup({
      firstName: new FormControl(saved.firstName, { nonNullable: true, validators: [minLength('First name')] }),
      lastName: new FormControl(saved.lastName, { nonNullable: true, validators: [minLength('Last name')] }),
      email,
      confirmEmail: new FormControl(saved.confirmEmail, {
        nonNullable: true,
        validators: [confirmEmailRule(email)],
      }),
      phone: new FormControl(saved.phone, { nonNullable: true, validators: [phoneRule] }),
      terms: new FormControl(saved.terms === true, { nonNullable: true, validators: [termsRule] }),
    });

    email.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => {
      this.form.controls.confirmEmail.updateValueAndValidity({ emitEvent: false });
    });
    this.form.valueChanges.pipe(takeUntilDestroyed()).subscribe(() => {
      this.booking.saveForm(this.form.getRawValue());
    });
  }

  protected error(name: keyof Checkout['form']['controls']): string | null {
    const control = this.form.controls[name];
    return control.touched ? (control.errors?.['msg'] ?? null) : null;
  }

  protected setTerms(checked: boolean): void {
    const terms = this.form.controls.terms;
    terms.setValue(checked);
    terms.markAsTouched();
  }

  protected back(): void {
    void this.router.navigate(['/screenings', this.screeningId, 'summary']);
  }

  protected pay(): void {
    if (this.processing()) {
      return;
    }
    if (this.form.invalid) {
      this.form.markAllAsTouched();
      this.toast.show('The form contains errors');
      return;
    }
    const { firstName, lastName, email, phone } = this.form.getRawValue();
    this.processing.set(true);
    this.api
      .createReservation({
        screeningId: this.screeningId!,
        seats: this.booking.items().flatMap((item) => item.ids),
        customer: { firstName, lastName, email, phone },
        totalPrice: this.booking.total(),
      })
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe({
        next: () => {
          this.booking.markPaid(email);
          void this.router.navigateByUrl('/confirmation');
        },
        error: () => {
          this.processing.set(false);
          this.toast.show('Payment failed. Please try again.');
        },
      });
  }
}

import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { Router, provideRouter } from '@angular/router';
import { RouterTestingHarness } from '@angular/router/testing';
import { MovieList } from './movie-list';

describe('MovieList', () => {
  beforeEach(() => {
    vi.useFakeTimers({ toFake: ['Date'] });
    vi.setSystemTime(new Date(2026, 8, 15, 10, 0));
    TestBed.configureTestingModule({
      providers: [
        provideRouter([{ path: '', component: MovieList }]),
        provideHttpClient(),
        provideHttpClientTesting(),
        provideNativeDateAdapter(),
      ],
    });
  });
  afterEach(() => vi.useRealTimers());

  const movies = [
    { id: 1, title: 'A', genre: 'Drama', runtimeMinutes: 128, format: 'PL dubbing' },
    { id: 2, title: 'B', genre: 'Comedy', runtimeMinutes: 90, format: 'PL subtitles' },
  ];
  const screenings = [
    { id: 1, movieId: 1, date: '2026-09-15', time: '18:00', occupiedSeats: [] },
    { id: 2, movieId: 1, date: '2026-09-15', time: '16:00', occupiedSeats: [] },
    { id: 3, movieId: 2, date: '2026-09-16', time: '12:00', occupiedSeats: [] },
  ];

  const texts = (el: HTMLElement, id: string) =>
    Array.from(el.querySelectorAll(`[data-testid="${id}"]`)).map((e) => e.textContent?.trim());

  it('shows loading, then today\'s movies with ordered screenings, and filters by day', async () => {
    const harness = await RouterTestingHarness.create('/');
    const el = harness.routeNativeElement as HTMLElement;
    const http = TestBed.inject(HttpTestingController);
    expect(texts(el, 'movies-loading')).toEqual(['Loading…']);
    expect(texts(el, 'movie-card')).toEqual([]);
    http.expectOne('http://localhost:3000/movies').flush(movies);
    http.expectOne('http://localhost:3000/screenings').flush(screenings);
    await harness.fixture.whenStable();

    expect(texts(el, 'day-button')).toEqual(['Today', 'Wednesday', 'Thursday', 'Friday', 'Saturday']);
    expect(Array.from(el.querySelectorAll('[data-testid=day-button]')).map((b) => b.getAttribute('data-selected'))).toEqual([
      'true', 'false', 'false', 'false', 'false',
    ]);
    expect(texts(el, 'movie-card')).toHaveLength(1);
    expect(texts(el, 'screening-button')).toEqual(['16:00', '18:00']);
    expect(texts(el, 'movie-runtime')).toEqual(['128 min']);

    el.querySelectorAll<HTMLElement>('[data-testid=day-button]')[1].click();
    await harness.fixture.whenStable();
    expect(TestBed.inject(Router).url).toBe('/?date=2026-09-16');
    expect(texts(el, 'movie-title')).toEqual(['B']);

    el.querySelectorAll<HTMLElement>('[data-testid=day-button]')[2].click();
    await harness.fixture.whenStable();
    expect(texts(el, 'movies-empty')).toEqual(['No screenings on this day']);
    expect(texts(el, 'movie-card')).toEqual([]);
  });

  it('falls back to today for past or invalid dates and offers retry on error', async () => {
    const harness = await RouterTestingHarness.create('/?date=2026-09-01');
    const el = harness.routeNativeElement as HTMLElement;
    const http = TestBed.inject(HttpTestingController);
    http.expectOne('http://localhost:3000/movies').flush(movies);
    http.expectOne('http://localhost:3000/screenings').flush('x', { status: 500, statusText: 'err' });
    await harness.fixture.whenStable();
    expect(texts(el, 'movies-error')).toEqual(['Failed to load movies']);
    expect(el.querySelector('[data-testid=day-button]')?.getAttribute('data-selected')).toBe('true');
    el.querySelector<HTMLElement>('[data-testid=movies-retry-button]')!.click();
    await harness.fixture.whenStable();
    expect(texts(el, 'movies-loading')).toEqual(['Loading…']);
    http.expectOne('http://localhost:3000/movies').flush(movies);
    http.expectOne('http://localhost:3000/screenings').flush(screenings);
    await harness.fixture.whenStable();
    expect(texts(el, 'movie-card')).toHaveLength(1);
  });
});

import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { ActivatedRoute, provideRouter } from '@angular/router';
import { BookingStore } from '../core/booking';
import { SeatMap } from './seat-map';

describe('SeatMap', () => {
  beforeEach(() => {
    sessionStorage.clear();
    TestBed.configureTestingModule({
      providers: [
        provideRouter([]),
        provideHttpClient(),
        provideHttpClientTesting(),
        provideNativeDateAdapter(),
        { provide: ActivatedRoute, useValue: { snapshot: { paramMap: new Map([['id', '1']]) } } },
      ],
    });
  });

  async function open() {
    const fixture = TestBed.createComponent(SeatMap);
    const http = TestBed.inject(HttpTestingController);
    http.expectOne('http://localhost:3000/screenings/1').flush({
      id: 1,
      movieId: 1,
      date: '2026-09-15',
      time: '16:00',
      occupiedSeats: ['R3C7', 'R15C5', 'R15C6', 'R1C10', 'R9C9'],
    });
    http.expectOne('http://localhost:3000/movies/1').flush({ id: 1 });
    await fixture.whenStable();
    return fixture.nativeElement as HTMLElement;
  }

  const q = (el: HTMLElement, id: string) => Array.from(el.querySelectorAll<HTMLElement>(`[data-testid="${id}"]`));

  it('renders the auditorium', async () => {
    const el = await open();
    expect(q(el, 'seat').length + q(el, 'couch').length).toBe(308);
    expect(q(el, 'seat-row')).toHaveLength(15);
    expect(q(el, 'aisle')).toHaveLength(30);
    expect(q(el, 'row-label-left')).toHaveLength(15);
    expect(q(el, 'seat-map-subtitle')[0].textContent).toBe('Show Date: Tuesday 15 Sep 16:00');
    const states = (sel: string) => el.querySelector(sel)?.getAttribute('data-state');
    expect(states('[data-testid=seat][data-row="3"][data-column="7"]')).toBe('unavailable');
    expect(states('[data-testid=seat][data-row="1"][data-column="10"]')).toBe('unavailable');
    expect(states('[data-testid=seat][data-row="1"][data-column="11"]')).toBe('accessible');
    expect(states('[data-testid=couch][data-column-start="5"]')).toBe('unavailable');
    expect(q(el, 'seat').find((s) => s.dataset['row'] === '1' && s.dataset['column'] === '11')?.textContent).toBe('11');
  });

  it('selects seats, caps at 10 seats and counts couches as 2', async () => {
    const el = await open();
    const click = async (sel: string) => {
      el.querySelector<HTMLElement>(sel)!.click();
      TestBed.tick();
    };
    await click('[data-testid=seat][data-row="7"][data-column="12"]');
    await click('[data-testid=seat][data-row="7"][data-column="11"]');
    await click('[data-testid=couch][data-column-start="1"]');
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 4');
    expect(q(el, 'selected-seats-row').map((r) => r.textContent)).toEqual(['Row 7: 11, 12', 'Row 15: 1-2']);
    await click('[data-testid=seat][data-row="7"][data-column="11"]');
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 3');

    for (let column = 5; column <= 11; column++) {
      await click(`[data-testid=seat][data-row="12"][data-column="${column}"]`);
    }
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 10');
    await click('[data-testid=seat][data-row="12"][data-column="20"]');
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 10');
    await click('[data-testid=couch][data-column-start="1"]');
    expect(q(el, 'selected-seats-count')[0].textContent).toBe('Selected seats: 8');
    expect(TestBed.inject(BookingStore).seats()).toHaveLength(8);
    expect(JSON.parse(sessionStorage.getItem('cinescope.booking')!).seats).toHaveLength(8);
  });
});
